<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>HG-P01 · Package screens — wireframes from live screens</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@600;700;800&family=IBM+Plex+Sans:wght@300;400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root{
  --ink:#1A1D21; --ink-2:#4A5056; --ink-3:#7B8288;
  --paper:#FFFFFF; --paper-2:#F7F7F8; --paper-3:#EFEFF1;
  --wire:#C9CDD2; --wire-2:#9AA0A6; --wire-fill:#E8EAEC;
  --note:#0B6E99; --note-bg:#E8F2F7;
  --warn:#A6561A; --warn-bg:#FBF1E8;
  --ok:#1C6B45; --ok-bg:#E8F1EC;
  --new:#7B2D8E; --new-bg:#F4EAF7;
  --disp:'Archivo',sans-serif; --body:'IBM Plex Sans',sans-serif; --mono:'IBM Plex Mono',monospace;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:1.5rem}
body{font-family:var(--body);background:var(--paper-2);color:var(--ink);line-height:1.6;font-size:15px;-webkit-font-smoothing:antialiased}
.shell{display:grid;grid-template-columns:238px 1fr;max-width:1520px;margin:0 auto;background:var(--paper)}
.nav{position:sticky;top:0;height:100vh;overflow-y:auto;border-right:1px solid var(--paper-3);padding:1.8rem 1.15rem 3rem;background:var(--paper-2)}
.main{padding:2.5rem 3.2vw 8rem;max-width:1080px;min-width:0}

.nav-brand{font-family:var(--disp);font-weight:800;font-size:.94rem;line-height:1.3}
.nav-sub{font-size:.71rem;color:var(--ink-3);margin:.3rem 0 1.3rem}
.nav-grp{font-family:var(--disp);font-weight:700;font-size:.62rem;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-3);margin:1.25rem 0 .38rem}
.nav a{display:block;font-size:.79rem;color:var(--ink-2);text-decoration:none;padding:.25rem .5rem;border-radius:3px}
.nav a:hover{color:var(--note);background:var(--paper)}
.nav a.nw::after{content:'NEW';font-family:var(--disp);font-size:.52rem;font-weight:800;background:var(--new);color:#fff;padding:.05rem .25rem;border-radius:2px;margin-left:.3rem;vertical-align:super}

h1{font-family:var(--disp);font-weight:800;font-size:clamp(1.65rem,3.3vw,2.3rem);line-height:1.15;letter-spacing:-.02em}
h2{font-family:var(--disp);font-weight:800;font-size:1.32rem;margin:3rem 0 .4rem;padding-top:1.25rem;border-top:2px solid var(--ink)}
h2:first-of-type{margin-top:1.9rem}
h3{font-family:var(--disp);font-weight:700;font-size:1.02rem;margin:1.7rem 0 .45rem}
h4{font-family:var(--disp);font-weight:700;font-size:.73rem;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3);margin:1.25rem 0 .38rem}
p{margin-bottom:.75rem;max-width:74ch;color:var(--ink-2)}
.lead{font-size:1rem;color:var(--ink-2);font-weight:300;max-width:66ch}
strong{font-weight:600;color:var(--ink)}
code{font-family:var(--mono);font-size:.84em;background:var(--paper-3);padding:.1em .34em;border-radius:2px}
.eyebrow{font-family:var(--disp);font-weight:700;font-size:.69rem;letter-spacing:.11em;text-transform:uppercase;color:var(--note);margin-bottom:.8rem}

.note{padding:.85rem 1.1rem;border-radius:3px;margin:1rem 0;font-size:.89rem;border-left:3px solid var(--note);background:var(--note-bg)}
.note.warn{border-left-color:var(--warn);background:var(--warn-bg)}
.note.ok{border-left-color:var(--ok);background:var(--ok-bg)}
.note.new{border-left-color:var(--new);background:var(--new-bg)}
.note b{font-family:var(--disp);font-weight:700;display:block;margin-bottom:.22rem;font-size:.79rem;color:var(--note)}
.note.warn b{color:var(--warn)} .note.ok b{color:var(--ok)} .note.new b{color:var(--new)}
.note p{margin:0;font-size:.89rem;color:var(--ink-2)}
.note p+p{margin-top:.45rem}

table{width:100%;border-collapse:collapse;font-size:.86rem;margin:1rem 0}
th{font-family:var(--disp);font-weight:700;font-size:.69rem;letter-spacing:.05em;text-transform:uppercase;text-align:left;padding:.52rem .68rem;border-bottom:2px solid var(--ink)}
td{padding:.52rem .68rem;border-bottom:1px solid var(--paper-3);vertical-align:top;color:var(--ink-2)}
tr:last-child td{border-bottom:none}
td.mono{font-family:var(--mono);font-size:.79rem}
td.num{font-family:var(--mono);text-align:right;color:var(--ink)}
.tagnew,.tagkeep,.tagchg{display:inline-block;font-family:var(--disp);font-weight:800;font-size:.58rem;color:#fff;padding:.08rem .3rem;border-radius:2px;vertical-align:middle;letter-spacing:.04em}
.tagnew{background:var(--new)} .tagkeep{background:var(--ok)} .tagchg{background:var(--warn)}

.wf{border:1px solid var(--wire-2);background:var(--paper);margin:1.3rem 0;border-radius:2px}
.wf-cap{font-family:var(--mono);font-size:.71rem;color:var(--ink-3);padding:.38rem .8rem;background:var(--paper-3);border-bottom:1px solid var(--wire);display:flex;justify-content:space-between;gap:.6rem;flex-wrap:wrap}
.wf-body{padding:1rem}
.wf-row{display:flex;gap:.55rem;margin-bottom:.55rem;align-items:stretch}
.wf-row:last-child{margin-bottom:0}
.box{border:1px solid var(--wire);background:var(--wire-fill);padding:.5rem .65rem;font-family:var(--mono);font-size:.73rem;color:var(--ink-3);border-radius:2px}
.box.in{background:var(--paper)}
.box.lbl{background:none;border:none;padding:.45rem 0;color:var(--ink-2);font-family:var(--body);font-size:.79rem;font-weight:600}
.box.btn{background:var(--ink);color:var(--paper);border-color:var(--ink);text-align:center;font-weight:500;font-family:var(--body)}
.box.dash{border-style:dashed;background:var(--paper)}
.box.nw{border:2px solid var(--new);background:var(--new-bg)}
.f1{flex:1}.f2{flex:2}.f3{flex:3}
.h36{min-height:36px}
.stk{display:flex;flex-direction:column;gap:.38rem}

.mk{display:inline-flex;align-items:center;justify-content:center;width:1.2rem;height:1.2rem;border-radius:50%;background:var(--note);color:#fff;font-family:var(--disp);font-weight:800;font-size:.66rem;flex:0 0 auto;margin-right:.35rem;vertical-align:middle}
.mk.nw{background:var(--new)}
.anno-list{margin:.9rem 0 1.5rem;list-style:none}
.anno-list li{display:grid;grid-template-columns:1.55rem 1fr;gap:.45rem;margin-bottom:.55rem;font-size:.87rem;color:var(--ink-2);align-items:start}
.anno-list li .mk{margin:.08rem 0 0 0}
.anno-list li b{color:var(--ink)}

.pcard{border:1px solid var(--wire);border-radius:3px;background:var(--paper);display:grid;grid-template-columns:120px 1fr 175px;overflow:hidden;margin-bottom:.5rem}
.pcard .ph{background:repeating-linear-gradient(45deg,var(--wire-fill),var(--wire-fill) 6px,var(--paper-3) 6px,var(--paper-3) 12px);display:flex;align-items:center;justify-content:center;color:var(--wire-2);font-family:var(--mono);font-size:.68rem;border-right:1px solid var(--wire)}
.pcard .pb{padding:.65rem .8rem}
.pcard .pt{font-size:.85rem;font-weight:600;color:var(--ink)}
.pcard .pm{font-family:var(--mono);font-size:.69rem;color:var(--ink-3);margin-top:.28rem;line-height:1.75}
.pcard .pc{border-left:1px solid var(--wire);padding:.65rem .8rem;text-align:right;display:flex;flex-direction:column;justify-content:space-between}

.rt{border:1px solid var(--wire);border-radius:3px;overflow:hidden;margin-bottom:.55rem;background:var(--paper)}
.rt-h{background:var(--paper-3);padding:.5rem .8rem;border-bottom:1px solid var(--wire);display:flex;justify-content:space-between;align-items:center;gap:.6rem;flex-wrap:wrap}
.rt-h .rn{font-size:.86rem;font-weight:600;color:var(--ink)}
.beds{display:flex;gap:.25rem;flex-wrap:wrap;margin-top:.22rem}
.bed{font-family:var(--mono);font-size:.62rem;border:1px solid var(--wire-2);background:var(--paper);padding:.05rem .32rem;border-radius:2px;color:var(--ink-3)}
.rt-cols,.rt-row{display:grid;grid-template-columns:2.2fr 1fr 1.3fr 1.1fr;gap:.5rem}
.rt-cols{padding:.35rem .8rem;background:var(--paper-2);border-bottom:1px solid var(--paper-3);font-family:var(--disp);font-weight:700;font-size:.62rem;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-3)}
.rt-row{padding:.55rem .8rem;border-bottom:1px solid var(--paper-3);align-items:center;font-size:.78rem}
.rt-row:last-child{border-bottom:none}
.rt-row.on{background:var(--new-bg)}
.rt-row .bp{color:var(--ink-2)}
.rt-row .bp small{display:block;font-size:.68rem;color:var(--ok)}
.rt-row .gs{font-family:var(--mono);font-size:.76rem;color:var(--ink)}
.rt-row .pr{font-family:var(--mono);font-size:.82rem;color:var(--ink);text-align:right}
.rt-row .pr small{display:block;font-size:.65rem;color:var(--ink-3);font-family:var(--body)}
.step{display:flex;align-items:center;gap:.3rem;justify-content:flex-end}
.step i{width:1.25rem;height:1.25rem;border:1px solid var(--wire-2);border-radius:2px;display:flex;align-items:center;justify-content:center;font-style:normal;font-size:.75rem;background:var(--paper);color:var(--ink-2)}
.step b{font-family:var(--mono);min-width:1rem;text-align:center;font-size:.8rem}

.csum{border:2px solid var(--new);border-radius:3px;background:var(--new-bg);padding:.65rem .85rem;margin:.55rem 0;font-size:.8rem}
.csum .ct{font-family:var(--disp);font-weight:700;font-size:.72rem;text-transform:uppercase;letter-spacing:.05em;color:var(--new);margin-bottom:.3rem}
.csum-row{display:flex;justify-content:space-between;gap:.6rem;padding:.16rem 0;font-family:var(--mono);font-size:.75rem;color:var(--ink-2)}
.csum-row.t{border-top:1px solid var(--new);margin-top:.3rem;padding-top:.35rem;font-weight:600;color:var(--ink)}

.addon{display:grid;grid-template-columns:1.15rem 1fr auto;gap:.6rem;padding:.5rem .8rem;border-bottom:1px solid var(--paper-3);align-items:center;font-size:.8rem}
.addon:last-child{border-bottom:none}
.addon .chk{width:.95rem;height:.95rem;border:1px solid var(--wire-2);border-radius:2px;background:var(--paper)}
.addon .chk.on{background:var(--new);border-color:var(--new)}
.addon .ap{font-family:var(--mono);font-size:.78rem;text-align:right;white-space:nowrap}
.addon .ap small{display:block;font-size:.64rem;color:var(--ink-3);font-family:var(--body)}

.pp{border:1px solid var(--wire-2);border-radius:3px;background:var(--paper)}
.pp-h{padding:.5rem .75rem;background:var(--paper-3);border-bottom:1px solid var(--wire);font-family:var(--disp);font-weight:700;font-size:.7rem;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-2)}
.pl{display:flex;justify-content:space-between;gap:.6rem;padding:.35rem .75rem;font-size:.77rem;border-bottom:1px solid var(--paper-3);color:var(--ink-2)}
.pl span:last-child{font-family:var(--mono)}
.pl.sub{border-top:1px solid var(--wire);font-weight:500;color:var(--ink)}
.pl.tot{border-top:2px solid var(--ink);border-bottom:none;font-weight:600;color:var(--ink);font-size:.89rem;padding-top:.5rem}
.pl.nw{background:var(--new-bg)}

pre{background:var(--ink);color:#D8DEE4;padding:.9rem 1.1rem;border-radius:3px;overflow-x:auto;margin:.85rem 0;font-size:.76rem;line-height:1.7;font-family:var(--mono)}
pre .c{color:#7B8288;font-style:italic} pre .g{color:#7FD8A8} pre .y{color:#E8C97C} pre .p{color:#D89FE8}

.ac{list-style:none;margin:.45rem 0 .95rem}
.ac li{position:relative;padding-left:1.45rem;margin-bottom:.38rem;font-size:.88rem;color:var(--ink-2)}
.ac li::before{content:'';position:absolute;left:0;top:.42em;width:.62rem;height:.62rem;border:1.5px solid var(--ok);border-radius:2px}
.q{list-style:none;margin:.45rem 0}
.q li{position:relative;padding-left:1.45rem;margin-bottom:.42rem;font-size:.88rem;color:var(--ink-2)}
.q li::before{content:'?';position:absolute;left:.1rem;top:-.05rem;font-family:var(--disp);font-weight:800;color:var(--warn)}

@media print{.nav{display:none}.shell{grid-template-columns:1fr}.main{padding:0;max-width:none}
  .wf,table{page-break-inside:avoid}body{font-size:10pt}}
@media (max-width:1000px){
  .shell{grid-template-columns:1fr}
  .nav{position:static;height:auto;border-right:none;border-bottom:1px solid var(--paper-3)}
  .main{padding:2rem 5vw 5rem}
  .wf-row{flex-wrap:wrap}
  .pcard{grid-template-columns:1fr}
  .rt-cols,.rt-row{grid-template-columns:1fr 1fr}
}
</style>
</head>
<body>
<div class="shell">

<aside class="nav">
  <div class="nav-brand">HG-P01<br>Package screens</div>
  <div class="nav-sub">Wireframes from the<br>three live screens</div>

  <div class="nav-grp">Baseline</div>
  <a href="#now">What exists today</a>
  <a href="#changes">What changes</a>

  <div class="nav-grp">Wireframes</div>
  <a href="#wf1">1 · Select Package</a>
  <a href="#wf2">2 · Package Details</a>
  <a class="nw" href="#wf3">3 · Room combinations</a>
  <a class="nw" href="#wf4">4 · Add-ons selectable</a>
  <a class="nw" href="#wf5">5 · Live price panel</a>
  <a href="#wf6">6 · Mobile</a>

  <div class="nav-grp">Detail</div>
  <a href="#calc">Price calculation</a>
  <a href="#states">States</a>
  <a href="#ac">Acceptance criteria</a>
  <a href="#questions">Open questions</a>
</aside>

<main class="main">

<div class="eyebrow">HotelGate · Olympics packages · Jeddah</div>
<h1>Select Package &amp; Package Details</h1>
<p class="lead" style="margin-top:.9rem">
  Wireframes built on the three screens you sent. Real data throughout — the Galleria,
  Novotel and ibis packages, the actual add-on prices, and the existing price-panel structure.
</p>

<h2 id="now">What exists today</h2>

<h3>Screen 1 — Select Package</h3>
<p>14 packages listed. Each card carries:</p>
<table>
  <thead><tr><th style="width:24%">Field</th><th>Live value</th></tr></thead>
  <tbody>
    <tr><td>Title</td><td>5 Stars ✨ Galleria Hotel arrival 12 Oct</td></tr>
    <tr><td><strong>Price label</strong></td><td class="mono">SAR 4310.27 — labelled <strong>"Total price"</strong> <span class="tagchg">CHANGES</span></td></tr>
    <tr><td>City</td><td>Jeddah</td></tr>
    <tr><td>Hotel Name</td><td>The Hotel Galleria Jeddah, Curio Collection by Hilton</td></tr>
    <tr><td>Night</td><td class="mono">6</td></tr>
    <tr><td>Category</td><td>Olympics 5-Star ⭐⭐⭐⭐⭐ Hotels</td></tr>
    <tr><td>Cancelation Policy</td><td>link</td></tr>
    <tr><td>Action</td><td>Select Package</td></tr>
  </tbody>
</table>
<p>Search summary above the list: <code>Country Egypt · Room 1 · Single rooms 1 · Passengers 1 · Date 11-10-2026 – 20-10-2026</code></p>

<h3>Screen 2 — Package Details</h3>
<p>Header shows <code>No of rooms: 1 (1 Single rooms - 0 Double rooms - 0 Suites)</code> and <code>Passengers: 1</code>. Then a hotel block, then add-ons, then the price panel:</p>
<table>
  <thead><tr><th style="width:36%">Line</th><th class="num">Value</th><th>Note</th></tr></thead>
  <tbody>
    <tr><td>Package Price</td><td class="num">3,748.06</td><td><span class="tagkeep">KEEP</span></td></tr>
    <tr><td>Discount</td><td class="num">0.00</td><td><span class="tagkeep">KEEP</span></td></tr>
    <tr><td>TAX</td><td class="num">562.21</td><td><span class="tagkeep">KEEP</span></td></tr>
    <tr><td><strong>Total Include vat</strong></td><td class="num"><strong>4,310.27</strong></td><td><span class="tagkeep">KEEP</span></td></tr>
  </tbody>
</table>
<p>Footer strip states: <em>"The final price includes Breakfast · Taxes · Transfers included: airport → hotel → event venue → back to airport"</em></p>

<div class="note warn">
  <b>The finding that matters most</b>
  <p>Add-ons today are <strong>informational only</strong>. The screen says: <em>"Add-ons are NOT included in the package price and are not part of this payment. To book any add-on, please complete your package payment first, then contact us by email or WhatsApp."</em></p>
  <p>What you're asking for — selectable add-ons summed into the total — is not a UI tweak. It moves add-ons <strong>into the payment</strong>. That needs a commercial decision before design, not after. See open question 1.</p>
</div>

<h3>Screen 3 — the hotel room table (the pattern to reuse)</h3>
<p>This is the hotel booking flow, not packages. Its room selector is the pattern you pointed at:</p>
<table>
  <thead><tr><th style="width:26%">Element</th><th>Detail</th></tr></thead>
  <tbody>
    <tr><td>Room heading</td><td><strong>Double Classic Room</strong> + bed-type chips: Queen Bed · Twin Beds · Bunk Bed · King Bed · Single Bed · Sofa Bed · Double Bed</td></tr>
    <tr><td>Columns</td><td><strong>Board &amp; Policy | Number Of Guests | Price Per Night | Select Room</strong></td></tr>
    <tr><td>Row content</td><td>Breakfast · Free cancellation before 02-10-2026 · price · <em>Price breakdown</em> link · quantity stepper</td></tr>
    <tr><td>Above the list</td><td>"Available Rooms (2)" · Filter: Board Type · Policy · Room Type · Price Type · Show Deals toggle</td></tr>
    <tr><td>Search bar</td><td>Modify your search criteria — Check In/Out · Rooms · Adults · Children · Modify Search</td></tr>
  </tbody>
</table>

<div class="note">
  <b>Worth noting</b>
  <p>Screen 3's search bar already has <strong>Adults</strong> and <strong>Children</strong> as separate fields. Screen 1's does not — it has "Room · Single rooms · Passengers". The hotel flow is ahead of the package flow here, and the package search needs to catch up before combinations can work.</p>
</div>

<h2 id="changes">What changes</h2>
<table>
  <thead><tr><th style="width:22%">Screen</th><th style="width:30%">Change</th><th>Why</th></tr></thead>
  <tbody>
    <tr><td>Select Package</td><td><span class="tagchg">CHANGE</span> "Total price" → <strong>"From"</strong></td><td>Once rooms are selectable the card can't show a total — it shows the cheapest arrangement</td></tr>
    <tr><td>Select Package</td><td><span class="tagnew">NEW</span> arrangement count</td><td>Tells the traveller choices exist before they click</td></tr>
    <tr><td>Select Package</td><td><span class="tagchg">CHANGE</span> search takes adults + children</td><td>Match screen 3. Needed to price a child at all</td></tr>
    <tr><td>Package Details</td><td><span class="tagnew">NEW</span> room combination block</td><td>Modelled on screen 3's table. The core of this story</td></tr>
    <tr><td>Package Details</td><td><span class="tagchg">CHANGE</span> add-ons become selectable</td><td>Currently informational — see the warning above</td></tr>
    <tr><td>Package Details</td><td><span class="tagchg">CHANGE</span> price panel recalculates live</td><td>Same four lines, now driven by selections</td></tr>
    <tr><td>Package Details</td><td><span class="tagkeep">KEEP</span> hotel block, inclusions strip, policy</td><td>Fixed package content, read-only</td></tr>
  </tbody>
</table>

<h2 id="wf1">Wireframe 1 · Select Package</h2>
<p>Same card anatomy as today. The changes are in the price column and the search summary.</p>

<div class="wf">
  <div class="wf-cap"><span>SCREEN 1 — Select Package</span><span>14 Packages Available</span></div>
  <div class="wf-body">
    <div class="wf-row"><div class="box dash f1" style="font-size:.71rem;padding:.55rem">
      <span class="mk">1</span> Country Egypt &nbsp;·&nbsp; Rooms 2 &nbsp;·&nbsp; Adults 4 &nbsp;·&nbsp; Children 1 (age 8) &nbsp;·&nbsp; 11-10-2026 → 20-10-2026 &nbsp;&nbsp;[ Modify Search ]
    </div></div>

    <div class="pcard">
      <div class="ph">image</div>
      <div class="pb">
        <div class="pt">5 Stars ✨ Galleria Hotel arrival 12 Oct</div>
        <div class="pm">
          City &nbsp;Jeddah<br>
          Hotel &nbsp;The Hotel Galleria Jeddah, Curio Collection by Hilton<br>
          Night &nbsp;6 &nbsp;·&nbsp; Category &nbsp;Olympics 5-Star ⭐⭐⭐⭐⭐<br>
          <span style="color:var(--ok)">✓ Breakfast &nbsp;✓ Taxes &nbsp;✓ Transfers</span> <span class="mk">2</span>
        </div>
        <div style="margin-top:.4rem;font-size:.72rem;color:var(--new);font-weight:600">
          <span class="mk nw">3</span> 5 room arrangements fit your party
        </div>
      </div>
      <div class="pc">
        <div>
          <div style="font-family:var(--disp);font-weight:700;font-size:.62rem;letter-spacing:.05em;color:var(--warn)">FROM <span class="mk">4</span></div>
          <div style="font-family:var(--mono);font-size:1.12rem;color:var(--ink);line-height:1.2">SAR 12,006<span style="font-size:.72rem">.00</span></div>
          <div style="font-size:.64rem;color:var(--ink-3)">total · 5 guests · 6 nights</div>
          <div style="font-size:.64rem;color:var(--ink-3);margin-top:.1rem">≈ SAR 2,401 / person</div>
        </div>
        <div>
          <div style="font-size:.64rem;color:var(--ink-3);margin-bottom:.3rem">Cancelation Policy</div>
          <div class="box btn" style="font-size:.72rem;padding:.42rem">Select Package</div>
        </div>
      </div>
    </div>

    <div class="pcard">
      <div class="ph">image</div>
      <div class="pb">
